const sd = $getWorkflowStaticData('global');
const now = Math.floor(Date.now() / 1000);
const http = (o) => this.helpers.httpRequest({ timeout: 20000, ...o });
const ago = s => s == null ? 'never' : s < 5400 ? `${Math.round(s/60)} min` : s < 172800 ? `${(s/3600).toFixed(1)} h` : `${Math.round(s/86400)} d`;
const msg = (tag, lines) => [{ json: { content: (`**[${tag}]** ` + [].concat(lines).join('\n')).slice(0, 1950) } }];
// Channel routing: an item with ch (daily|focus|stella|server) overrides the flow's default channel.
const hostCh = h => /server|immich/i.test(String(h)) ? 'server' : 'stella';
const msgTo = (ch, tag, lines) => msg(tag, lines).map(i => ({ json: { ...i.json, ch } }));
const msgByCh = (tag, pairs) => { const by = {}; for (const [ch, l] of pairs) (by[ch] = by[ch] || []).push(l);
  return Object.entries(by).flatMap(([ch, l]) => msgTo(ch, tag, l)); };

// Everything the voice service (or the laptop island) sent, plus a start time for the latency figure.
const b = $input.first().json.body || {};
return [{ json: { raw: String(b.text || '').trim(), pending: b.pending || null, dry: !!b.dry, source: b.source || 'voice', t0: Date.now(), at: new Date().toISOString() } }];

