// One shape for every reply, plus the decision and timing for the log and the dashboard.
const d = $('Intent decided').first().json, j = $input.first().json;
// An action with nothing to report gets a short "boss" acknowledgement; otherwise the reply stands alone.
const ACT = ['music', 'timer', 'reminder', 'claude', 'note', 'discord', 'laptop', 'routine', 'cancel'];
const QUIET = ['pause', 'resume', 'volume_up', 'volume_down', 'mute', 'unmute', 'status'];
const ACKS = ['On it, boss.', 'Got you, boss.', 'Okay boss.', 'Yes boss.'];
let say = String(j.say || '').trim();
const quiet = d.intent === 'music' && QUIET.includes((d.slots || {}).cmd);
if (ACT.includes(d.intent) && !quiet && !j.pending && !/\bboss\b/i.test(say) && !/^(sorry|i couldn|laptop isn|the music player|nothing)/i.test(say)) {
  const ack = ACKS[Math.floor(Math.random() * ACKS.length)];
  if (!say) say = ack;
}
return [{ json: { say, pending: j.pending || null, listen: !!j.listen, intent: d.intent, slots: d.slots,
  route_source: d.route_source, rule: d.rule || '', heard: d.raw, dry: d.dry, source: d.source, ms: Date.now() - d.t0,
  wait_s: j.wait_s || 0, wait_id: j.wait_id || '', ring: j.ring || '', discord: j.discord || '', kind: j.kind || '', no_remember: !!j.no_remember } }];

